begin;
set local search_path=public,extensions;
select plan(32);

select ok((select count(*)=8 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['franchise_finance_rule_versions','franchise_pnl_books','franchise_entry_fee_schedules','franchise_entry_fee_ledger_entries','franchise_pnl_entries','franchise_profit_closure_versions','franchise_profit_allocations','franchise_distribution_ledger_entries'])),'all franchise rule, fee, P&L, allocation and distribution tables exist');
select ok((select count(*)=8 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['franchise_finance_rule_versions','franchise_pnl_books','franchise_entry_fee_schedules','franchise_entry_fee_ledger_entries','franchise_pnl_entries','franchise_profit_closure_versions','franchise_profit_allocations','franchise_distribution_ledger_entries'])),'RLS is enabled on every franchise finance table');
select ok((select count(*)=8 from pg_policies where schemaname='public'and tablename=any(array['franchise_finance_rule_versions','franchise_pnl_books','franchise_entry_fee_schedules','franchise_entry_fee_ledger_entries','franchise_pnl_entries','franchise_profit_closure_versions','franchise_profit_allocations','franchise_distribution_ledger_entries'])),'every franchise finance table has an explicit read policy');
select ok((select count(*)=6 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_franchise_finance_rule','open_franchise_pnl_book','create_franchise_entry_fee_schedule','post_franchise_pnl_entry','close_franchise_profit_period','record_franchise_distribution_payout'])),'six public finance commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_franchise_finance_rule','open_franchise_pnl_book','create_franchise_entry_fee_schedule','post_franchise_pnl_entry','close_franchise_profit_period','record_franchise_distribution_payout'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anonymous and service roles cannot execute franchise finance commands');
select ok((select count(*)=6 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_franchise_finance_rule','open_franchise_pnl_book','create_franchise_entry_fee_schedule','post_franchise_pnl_entry','close_franchise_profit_period','record_franchise_distribution_payout'])),'authenticated users have only explicit command execution');
select ok(not has_table_privilege('authenticated','public.franchise_pnl_entries','INSERT')and not has_table_privilege('authenticated','public.franchise_profit_allocations','UPDATE')and not has_table_privilege('authenticated','public.franchise_distribution_ledger_entries','DELETE'),'direct ledger, allocation and distribution mutations are denied');
select ok((select count(*)=8 from pg_trigger where tgname=any(array['franchise_rules_immutable','franchise_books_immutable','franchise_fee_schedules_immutable','franchise_fee_ledger_immutable','franchise_pnl_entries_immutable','franchise_closures_immutable','franchise_allocations_immutable','franchise_distribution_immutable'])and not tgisinternal),'all economic rules and financial histories are immutable');
select ok((select count(*)=1 from pg_trigger where tgname='franchise_allocations_balanced'and tgdeferrable and tginitdeferred and not tgisinternal),'allocation total is enforced by a deferred database constraint');
select is((select entry_fee_required from public.franchise_finance_rule_versions where franchise_type='IT'and version=1),false,'Hatim IT entry fee is categorically exempt');
select is((select operator_code from public.franchise_finance_rule_versions where franchise_type='IT'and version=1),'HATIM_AHMITECH','IT operator is Hatim Ahmitech');
select is((select franchisee_share_bps from public.franchise_finance_rule_versions where franchise_type='IT'and version=1),5000,'Hatim receives 50 percent of IT distributable profit');
select is((select neoxa_share_bps from public.franchise_finance_rule_versions where franchise_type='IT'and version=1),5000,'Jalil-NEOXA receives 50 percent of IT distributable profit');
select is((select asma_matricia_share_bps from public.franchise_finance_rule_versions where franchise_type='IT'and version=1),0,'Asma-Matricia receives zero percent of the specific IT distribution');
select ok((select entry_fee_required and franchisee_share_bps=5000 and neoxa_share_bps=2500 and asma_matricia_share_bps=2500 from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),'standard default is mandatory entry fee and 50/25/25');
select ok((select formula_snapshot->>'vat_treatment'='EXCLUDED_FROM_REVENUE_AND_PROFIT'and formula_snapshot->>'shared_central_cost_policy'='EXCLUDED_UNLESS_EXPLICITLY_APPROVED_AND_VERSIONED'from public.franchise_finance_rule_versions where franchise_type='IT'and version=1),'VAT is excluded and central shared costs require an explicit versioned rule');
select ok((select count(*)>=5 from information_schema.columns where table_schema='public'and table_name in('franchise_entry_fee_schedules','franchise_pnl_entries','franchise_profit_closure_versions','franchise_profit_allocations','franchise_distribution_ledger_entries')and data_type='bigint'),'money is stored in exact bigint minor units');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name like'franchise_%'and data_type in('real','double precision')),'no floating-point franchise money exists');
select ok((select pg_get_constraintdef(oid)like'%HATIM_AHMITECH%'and pg_get_constraintdef(oid)like'%franchisee_share_bps = 5000%'and pg_get_constraintdef(oid)like'%asma_matricia_share_bps = 0%'from pg_constraint where conrelid='public.franchise_finance_rule_versions'::regclass and contype='c'and pg_get_constraintdef(oid)like'%franchise_type <>%'),'database constraints protect the permanent IT exception');
select ok((select pg_get_functiondef(p.oid)like'%IT_ENTRY_FEE_EXEMPT%'and pg_get_functiondef(p.oid)like'%p_principal_minor<>0%'and pg_get_functiondef(p.oid)like'%p_due_on%'and pg_get_functiondef(p.oid)like'%6 months%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_franchise_entry_fee_schedule'),'fee command enforces IT zero debt and six-month maximum for ordinary franchises');
select ok((select count(*)>=2 from pg_constraint where conrelid='public.franchise_pnl_entries'::regclass and contype='f'and pg_get_constraintdef(oid)like any(array['%financial_journal_id%','%reverses_entry_id%'])),'every P&L line is reconciled to the balanced journal and reversals preserve lineage');
select ok((select pg_get_functiondef(p.oid)like'%INVALID_PNL_REVERSAL%'and pg_get_functiondef(p.oid)like'%exists%'and pg_get_functiondef(p.oid)like'%reverses_entry_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='post_franchise_pnl_entry'),'P&L corrections are single append-only reversals');
select ok((select pg_get_functiondef(p.oid)not like'%VAT_COLLECTED%'and pg_get_functiondef(p.oid)like'%COLLECTED_NET_REVENUE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='post_franchise_pnl_entry'),'P&L accepts collected net revenue and never treats collected VAT as revenue');
select ok((select pg_get_functiondef(p.oid)like'%gross_revenue_ex_tax_minor%'and pg_get_functiondef(p.oid)like'%costs_and_refunds_minor%'and pg_get_functiondef(p.oid)like'%distributable_profit_minor%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='close_franchise_profit_period'),'closure records the explicit distributable-profit basis');
select ok((select pg_get_functiondef(p.oid)like'%to_jsonb(rv)%'and pg_get_functiondef(p.oid)like'%approved_by%'and pg_get_functiondef(p.oid)like'%formula_snapshot%'and pg_get_functiondef(p.oid)like'%content_hash%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='close_franchise_profit_period'),'each closure snapshots its economic rights and cost formula');
select ok((select pg_get_functiondef(p.oid)like'%greatest(profit,0)%'and pg_get_functiondef(p.oid)like'%franchise_type%'and pg_get_functiondef(p.oid)like'%na:=%'and pg_get_functiondef(p.oid)like'%rem%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='close_franchise_profit_period'),'negative profit distributes zero and IT remainder never creates an Asma allocation');
select ok((select pg_get_functiondef(p.oid)like'%prior.version%'and pg_get_functiondef(p.oid)like'%ADJUSTMENT%'and pg_get_functiondef(p.oid)like'%oldamt%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='close_franchise_profit_period'),'reclosing a corrected period appends only the allocation delta');
select ok((select pg_get_functiondef(p.oid)like'%INSUFFICIENT_DISTRIBUTABLE_BALANCE%'and pg_get_functiondef(p.oid)like'%pg_advisory_xact_lock%'and pg_get_functiondef(p.oid)like'%PAYOUT%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_franchise_distribution_payout'),'payout is serialized and cannot exceed the derived immutable balance');
select ok((select count(*)=6 and bool_and(pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%finish_contract_command%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_franchise_finance_rule','open_franchise_pnl_book','create_franchise_entry_fee_schedule','post_franchise_pnl_entry','close_franchise_profit_period','record_franchise_distribution_payout'])),'all six commands use canonical idempotency lifecycle');
select ok((select count(*)=6 and bool_and(pg_get_functiondef(p.oid)like'%audit_events%'and pg_get_functiondef(p.oid)like'%event_outbox%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_franchise_finance_rule','open_franchise_pnl_book','create_franchise_entry_fee_schedule','post_franchise_pnl_entry','close_franchise_profit_period','record_franchise_distribution_payout'])),'all six commands emit audit and Outbox records');
select ok((select p.prosecdef and pg_get_functiondef(p.oid)like'%FRANCHISE_ACCOUNTING%'and pg_get_functiondef(p.oid)like'%FINANCE_MANAGER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='franchise_book_access'),'tenant P&L access is isolated to franchise roles and central finance/audit');
select ok((select count(*)>=7 from pg_indexes where schemaname='public'and tablename=any(array['franchise_finance_rule_versions','franchise_pnl_books','franchise_entry_fee_ledger_entries','franchise_pnl_entries','franchise_profit_closure_versions','franchise_profit_allocations','franchise_distribution_ledger_entries'])),'rules, periods, balances and beneficiary queries are indexed');

select * from finish();
rollback;
